insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycolysis', 'Glycolysis is the metabolic pathway that converts glucose (C6H12O6) into pyruvate and, in most organisms, occurs in the liquid part of cells (the cytosol). The free energy released in this process is used to form the high-energy molecules adenosine triphosphate (ATP) and reduced nicotinamide adenine dinucleotide (NADH). Glycolysis is a sequence of ten reactions catalyzed by enzymes. The wide occurrence of glycolysis in other species indicates that it is an ancient metabolic pathway. Indeed, the reactions that make up glycolysis and its parallel pathway, the pentose phosphate pathway, can occur in the oxygen-free conditions of the Archean oceans, also in the absence of enzymes, catalyzed by metal ions, meaning this is a plausible prebiotic pathway for abiogenesis. The most common type of glycolysis is the Embden–Meyerhof–Parnas (EMP) pathway, which was discovered by Gustav Embden, Otto Meyerhof, and Jakub Karol Parnas. Glycolysis also refers to other pathways, such as the Entner–Doudoroff pathway and various heterofermentative and homofermentative pathways. However, the discussion here will be limited to the Embden–Meyerhof–Parnas pathway.', 'Wikipedia: Glycolysis', 'https://en.wikipedia.org/w/index.php?title=Glycolysis&oldid=1379254347', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Glycolysis is the metabolic pathway that converts glucose (C6H12O6) into pyruvate and, in most organisms, occurs in the liquid part of cells (the cytosol). The free energy released in this process is used to form the high-energy molecules adenosine triphosphate (ATP) and reduced nicotinamide adenine dinucleotide (NADH). Glycolysis is a sequence of ten reactions catalyzed by enzymes. The wide occurrence of glycolysis in other species indicates that it is an ancient metabolic pathway. Indeed, the reactions that make up glycolysis and its parallel pathway, the pentose phosphate pathway, can occur in the oxygen-free conditions of the Archean oceans, also in the absence of enzymes, catalyzed by metal ions, meaning this is a plausible prebiotic pathway for abiogenesis. The most common type of glycolysis is the Embden–Meyerhof–Parnas (EMP) pathway, which was discovered by Gustav Embden, Otto Meyerhof, and Jakub Karol Parnas. Glycolysis also refers to other pathways, such as the Entner–Doudoroff pathway and various heterofermentative and homofermentative pathways. However, the discussion here will be limited to the Embden–Meyerhof–Parnas pathway.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycolysis: Overview', 'The use of symbols in this equation makes it appear unbalanced with respect to oxygen atoms, hydrogen atoms, and charges. Atom balance is maintained by the two phosphate (Pi) groups: Each exists in the form of a hydrogen phosphate anion ([HPO4]2−), dissociating to contribute 2H+ overall Each liberates an oxygen atom when it binds to an adenosine diphosphate (ADP) molecule, contributing 2 O overall Charges are balanced by the difference between ADP and ATP. In the cellular environment, all three hydroxyl groups of ADP dissociate into −O− and H+, giving ADP3−, and this ion tends to exist in an ionic bond with Mg2+, giving ADPMg−. ATP behaves identically except that it has four hydroxyl groups, giving ATPMg3−. When these differences along with the true charges on the two phosphate groups are considered together, the net charges of −4 on each side are balanced. In high-oxygen (aerobic) conditions, eukaryotic cells can continue from glycolysis to metabolise the pyruvate through the citric acid cycle or the electron transport chain to produce significantly more ATP.', 'Wikipedia: Glycolysis', 'https://en.wikipedia.org/w/index.php?title=Glycolysis&oldid=1379254347', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The use of symbols in this equation makes it appear unbalanced with respect to oxygen atoms, hydrogen atoms, and charges. Atom balance is maintained by the two phosphate (Pi) groups: Each exists in the form of a hydrogen phosphate anion ([HPO4]2−), dissociating to contribute 2H+ overall Each liberates an oxygen atom when it binds to an adenosine diphosphate (ADP) molecule, contributing 2 O overall Charges are balanced by the difference between ADP and ATP. In the cellular environment, all three hydroxyl groups of ADP dissociate into −O− and H+, giving ADP3−, and this ion tends to exist in an ionic bond with Mg2+, giving ADPMg−. ATP behaves identically except that it has four hydroxyl groups, giving ATPMg3−. When these differences along with the true charges on the two phosphate groups are considered together, the net charges of −4 on each side are balanced. In high-oxygen (aerobic) conditions, eukaryotic cells can continue from glycolysis to metabolise the pyruvate through the citric acid cycle or the electron transport chain to produce significantly more ATP.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycolysis: Overview', 'Importantly, under low-oxygen (anaerobic) conditions, glycolysis is the only biochemical pathway in eukaryotes that can generate ATP, and, for many anaerobic respiring organisms the most important producer of ATP. Therefore, many organisms have evolved fermentation pathways to recycle NAD+ to continue glycolysis to produce ATP for survival. These pathways include ethanol fermentation and lactic acid fermentation.', 'Wikipedia: Glycolysis', 'https://en.wikipedia.org/w/index.php?title=Glycolysis&oldid=1379254347', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Importantly, under low-oxygen (anaerobic) conditions, glycolysis is the only biochemical pathway in eukaryotes that can generate ATP, and, for many anaerobic respiring organisms the most important producer of ATP. Therefore, many organisms have evolved fermentation pathways to recycle NAD+ to continue glycolysis to produce ATP for survival. These pathways include ethanol fermentation and lactic acid fermentation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycolysis: Preparatory phase', 'The first five steps of glycolysis are regarded as the preparatory (or investment) phase, since they consume energy to convert the glucose into two three-carbon sugar phosphates (G3P). Once glucose enters the cell, the first step is phosphorylation of glucose by a family of enzymes called hexokinases to form glucose 6-phosphate (G6P). This reaction consumes ATP, but it acts to keep the glucose concentration inside the cell low, promoting continuous transport of blood glucose into the cell through the plasma membrane transporters. In addition, phosphorylation blocks the glucose from leaking out – the cell lacks transporters for G6P, and free diffusion out of the cell is prevented due to the charged nature of G6P. Glucose may alternatively be formed from the phosphorolysis or hydrolysis of intracellular starch or glycogen. In animals, an isozyme of hexokinase called glucokinase is also used in the liver, which has a much lower affinity for glucose (Km in the vicinity of normal glycemia), and differs in regulatory properties. The various substrate affinities and regulation of this enzyme reflect the role of the liver in maintaining blood sugar levels. G6P is then rearranged into fructose 6-phosphate (F6P) by glucose phosphate isomerase. Fructose can also enter the glycolytic pathway by phosphorylation at this point.', 'Wikipedia: Glycolysis', 'https://en.wikipedia.org/w/index.php?title=Glycolysis&oldid=1379254347', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The first five steps of glycolysis are regarded as the preparatory (or investment) phase, since they consume energy to convert the glucose into two three-carbon sugar phosphates (G3P). Once glucose enters the cell, the first step is phosphorylation of glucose by a family of enzymes called hexokinases to form glucose 6-phosphate (G6P). This reaction consumes ATP, but it acts to keep the glucose concentration inside the cell low, promoting continuous transport of blood glucose into the cell through the plasma membrane transporters. In addition, phosphorylation blocks the glucose from leaking out – the cell lacks transporters for G6P, and free diffusion out of the cell is prevented due to the charged nature of G6P. Glucose may alternatively be formed from the phosphorolysis or hydrolysis of intracellular starch or glycogen. In animals, an isozyme of hexokinase called glucokinase is also used in the liver, which has a much lower affinity for glucose (Km in the vicinity of normal glycemia), and differs in regulatory properties. The various substrate affinities and regulation of this enzyme reflect the role of the liver in maintaining blood sugar levels. G6P is then rearranged into fructose 6-phosphate (F6P) by glucose phosphate isomerase. Fructose can also enter the glycolytic pathway by phosphorylation at this point.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycolysis: Preparatory phase', 'The change in structure is an isomerization, in which the G6P has been converted to F6P. The reaction requires an enzyme, phosphoglucose isomerase, to proceed. This reaction is freely reversible under normal cell conditions. However, it is often driven forward because of a low concentration of F6P, which is constantly consumed during the next step of glycolysis. Under conditions of high F6P concentration, this reaction readily runs in reverse. This phenomenon can be explained through Le Chatelier''s Principle. Isomerization to a keto sugar is necessary for carbanion stabilization in the fourth reaction step (below). The energy expenditure of another ATP in this step is justified in 2 ways: The glycolytic process (up to this step) becomes irreversible, and the energy supplied destabilizes the molecule. Because the reaction catalyzed by phosphofructokinase 1 (PFK-1) is coupled to the hydrolysis of ATP (an energetically favorable step) it is, in essence, irreversible, and a distinct pathway must be used to do the reverse conversion during gluconeogenesis. This makes the reaction a key regulatory point (see below). Furthermore, the second phosphorylation event is necessary to allow the formation of two charged groups (rather than only one) in the subsequent step of glycolysis, ensuring the prevention of free diffusion of substrates out of the cell.', 'Wikipedia: Glycolysis', 'https://en.wikipedia.org/w/index.php?title=Glycolysis&oldid=1379254347', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The change in structure is an isomerization, in which the G6P has been converted to F6P. The reaction requires an enzyme, phosphoglucose isomerase, to proceed. This reaction is freely reversible under normal cell conditions. However, it is often driven forward because of a low concentration of F6P, which is constantly consumed during the next step of glycolysis. Under conditions of high F6P concentration, this reaction readily runs in reverse. This phenomenon can be explained through Le Chatelier''s Principle. Isomerization to a keto sugar is necessary for carbanion stabilization in the fourth reaction step (below). The energy expenditure of another ATP in this step is justified in 2 ways: The glycolytic process (up to this step) becomes irreversible, and the energy supplied destabilizes the molecule. Because the reaction catalyzed by phosphofructokinase 1 (PFK-1) is coupled to the hydrolysis of ATP (an energetically favorable step) it is, in essence, irreversible, and a distinct pathway must be used to do the reverse conversion during gluconeogenesis. This makes the reaction a key regulatory point (see below). Furthermore, the second phosphorylation event is necessary to allow the formation of two charged groups (rather than only one) in the subsequent step of glycolysis, ensuring the prevention of free diffusion of substrates out of the cell.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycolysis: Preparatory phase', 'The same reaction can also be catalyzed by pyrophosphate-dependent phosphofructokinase (PFP or PPi-PFK), which is found in most plants, some bacteria, archea, and protists, but not in animals. This enzyme uses pyrophosphate (PPi) as a phosphate donor instead of ATP. It is a reversible reaction, increasing the flexibility of glycolytic metabolism. A rarer ADP-dependent PFK enzyme variant has been identified in archaean species. Destabilizing the molecule in the previous reaction allows the hexose ring to be split by aldolase into two triose sugars: dihydroxyacetone phosphate (a ketose), and glyceraldehyde 3-phosphate (an aldose). Two classes of aldolases exist: class I aldolases, present in animals and plants, and class II aldolases, present in fungi and bacteria. The two classes use distinct mechanisms in cleaving the ketose ring. Electrons delocalized in the carbon-carbon bond cleavage associate with the alcohol group. The resulting carbanion is stabilized by resonance and by a positively charged prosthetic group. Triosephosphate isomerase rapidly interconverts dihydroxyacetone phosphate with glyceraldehyde 3-phosphate (GADP) that proceeds further into glycolysis. This is advantageous, as it directs dihydroxyacetone phosphate down the same pathway as glyceraldehyde 3-phosphate, simplifying regulation.', 'Wikipedia: Glycolysis', 'https://en.wikipedia.org/w/index.php?title=Glycolysis&oldid=1379254347', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The same reaction can also be catalyzed by pyrophosphate-dependent phosphofructokinase (PFP or PPi-PFK), which is found in most plants, some bacteria, archea, and protists, but not in animals. This enzyme uses pyrophosphate (PPi) as a phosphate donor instead of ATP. It is a reversible reaction, increasing the flexibility of glycolytic metabolism. A rarer ADP-dependent PFK enzyme variant has been identified in archaean species. Destabilizing the molecule in the previous reaction allows the hexose ring to be split by aldolase into two triose sugars: dihydroxyacetone phosphate (a ketose), and glyceraldehyde 3-phosphate (an aldose). Two classes of aldolases exist: class I aldolases, present in animals and plants, and class II aldolases, present in fungi and bacteria. The two classes use distinct mechanisms in cleaving the ketose ring. Electrons delocalized in the carbon-carbon bond cleavage associate with the alcohol group. The resulting carbanion is stabilized by resonance and by a positively charged prosthetic group. Triosephosphate isomerase rapidly interconverts dihydroxyacetone phosphate with glyceraldehyde 3-phosphate (GADP) that proceeds further into glycolysis. This is advantageous, as it directs dihydroxyacetone phosphate down the same pathway as glyceraldehyde 3-phosphate, simplifying regulation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycolysis: Pay-off phase', 'The second half of glycolysis is known as the pay-off phase, characterised by a net gain of the energy-rich molecules ATP and NADH. Since glucose leads to two triose sugars in the preparatory phase, each reaction in the pay-off phase occurs twice per glucose molecule. This yields 2 NADH molecules and 4 ATP molecules, leading to a net gain of 2 NADH molecules and 2 ATP molecules from the glycolytic pathway per glucose. The aldehyde groups of the triose sugars are oxidised, and inorganic phosphate is added to them, forming 1,3-bisphosphoglycerate. The hydrogen is used to reduce two molecules of NAD+, a hydrogen carrier, to give NADH + H+ for each triose. Hydrogen atom and ion balance and charge balance are both maintained because the phosphate (Pi) group actually exists in the form of a hydrogen phosphate anion (HPO2−4), which dissociates to contribute the extra H+ ion and gives a net charge of −3 on both sides.', 'Wikipedia: Glycolysis', 'https://en.wikipedia.org/w/index.php?title=Glycolysis&oldid=1379254347', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The second half of glycolysis is known as the pay-off phase, characterised by a net gain of the energy-rich molecules ATP and NADH. Since glucose leads to two triose sugars in the preparatory phase, each reaction in the pay-off phase occurs twice per glucose molecule. This yields 2 NADH molecules and 4 ATP molecules, leading to a net gain of 2 NADH molecules and 2 ATP molecules from the glycolytic pathway per glucose. The aldehyde groups of the triose sugars are oxidised, and inorganic phosphate is added to them, forming 1,3-bisphosphoglycerate. The hydrogen is used to reduce two molecules of NAD+, a hydrogen carrier, to give NADH + H+ for each triose. Hydrogen atom and ion balance and charge balance are both maintained because the phosphate (Pi) group actually exists in the form of a hydrogen phosphate anion (HPO2−4), which dissociates to contribute the extra H+ ion and gives a net charge of −3 on both sides.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycolysis: Pay-off phase', 'Here, arsenate ([AsO4]3−), an anion akin to inorganic phosphate may replace phosphate as a substrate to form 1-arseno-3-phosphoglycerate. This, however, is unstable and readily hydrolyzes to form 3-phosphoglycerate, the intermediate in the next step of the pathway. As a consequence of bypassing this step, the molecule of ATP generated from 1–3 bisphosphoglycerate in the next reaction will not be made, even though the reaction proceeds. As a result, arsenate is an uncoupler of glycolysis. This step is the enzymatic transfer of a phosphate group from 1,3-bisphosphoglycerate to ADP by phosphoglycerate kinase, forming ATP and 3-phosphoglycerate. At this step, glycolysis has reached the break-even point: 2 molecules of ATP were consumed, and 2 new molecules have now been synthesized. This step, one of the two substrate-level phosphorylation steps, requires ADP; thus, when the cell has plenty of ATP (and little ADP), this reaction does not occur. Because ATP decays relatively quickly when it is not metabolized, this is an important regulatory point in the glycolytic pathway. ADP actually exists as ADPMg−, and ATP as ATPMg2−, balancing the charges at −5 both sides. Enolase next converts 2-phosphoglycerate to phosphoenolpyruvate. This reaction is an elimination reaction involving an E1cB mechanism.', 'Wikipedia: Glycolysis', 'https://en.wikipedia.org/w/index.php?title=Glycolysis&oldid=1379254347', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Here, arsenate ([AsO4]3−), an anion akin to inorganic phosphate may replace phosphate as a substrate to form 1-arseno-3-phosphoglycerate. This, however, is unstable and readily hydrolyzes to form 3-phosphoglycerate, the intermediate in the next step of the pathway. As a consequence of bypassing this step, the molecule of ATP generated from 1–3 bisphosphoglycerate in the next reaction will not be made, even though the reaction proceeds. As a result, arsenate is an uncoupler of glycolysis. This step is the enzymatic transfer of a phosphate group from 1,3-bisphosphoglycerate to ADP by phosphoglycerate kinase, forming ATP and 3-phosphoglycerate. At this step, glycolysis has reached the break-even point: 2 molecules of ATP were consumed, and 2 new molecules have now been synthesized. This step, one of the two substrate-level phosphorylation steps, requires ADP; thus, when the cell has plenty of ATP (and little ADP), this reaction does not occur. Because ATP decays relatively quickly when it is not metabolized, this is an important regulatory point in the glycolytic pathway. ADP actually exists as ADPMg−, and ATP as ATPMg2−, balancing the charges at −5 both sides. Enolase next converts 2-phosphoglycerate to phosphoenolpyruvate. This reaction is an elimination reaction involving an E1cB mechanism.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Citric acid cycle', 'The citric acid cycle—also known as the Krebs cycle, Szent–Györgyi–Krebs cycle, or TCA cycle (tricarboxylic acid cycle)—is a series of biochemical reactions that release the energy stored in nutrients through acetyl-CoA oxidation. The energy released is available in the form of ATP. The Krebs cycle is used by organisms that generate energy via respiration, either anaerobically or aerobically (organisms that ferment use different pathways). In addition, the cycle provides precursors of certain amino acids, as well as the reducing agent NADH, which are used in other reactions. Its central importance to many biochemical pathways suggests that it was one of the earliest metabolic components. Even though it is branded as a "cycle", it is not necessary for metabolites to follow a specific route; at least three alternative pathways of the citric acid cycle are recognized.', 'Wikipedia: Citric acid cycle', 'https://en.wikipedia.org/w/index.php?title=Citric_acid_cycle&oldid=1379847022', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The citric acid cycle—also known as the Krebs cycle, Szent–Györgyi–Krebs cycle, or TCA cycle (tricarboxylic acid cycle)—is a series of biochemical reactions that release the energy stored in nutrients through acetyl-CoA oxidation. The energy released is available in the form of ATP. The Krebs cycle is used by organisms that generate energy via respiration, either anaerobically or aerobically (organisms that ferment use different pathways). In addition, the cycle provides precursors of certain amino acids, as well as the reducing agent NADH, which are used in other reactions. Its central importance to many biochemical pathways suggests that it was one of the earliest metabolic components. Even though it is branded as a "cycle", it is not necessary for metabolites to follow a specific route; at least three alternative pathways of the citric acid cycle are recognized.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Citric acid cycle', 'Its name is derived from the citric acid (a tricarboxylic acid, often called citrate, as the ionized form predominates at biological pH) that is consumed and then regenerated by this sequence of reactions. The cycle consumes acetate (in the form of acetyl-CoA) and water and reduces NAD+ to NADH, releasing carbon dioxide. The NADH generated by the citric acid cycle is fed into the oxidative phosphorylation (electron transport) pathway. The net result of these two closely linked pathways is the oxidation of nutrients to produce usable chemical energy in the form of ATP. In eukaryotic cells, the citric acid cycle occurs in the mitochondrial matrix. In prokaryotic cells, such as bacteria, which lack mitochondria, the citric acid cycle reaction sequence is performed in the cytosol with the proton gradient for ATP production being across the cell''s surface (plasma membrane) rather than the inner membrane of the mitochondrion. For each pyruvate molecule (from glycolysis), the overall yield of energy-containing compounds from the citric acid cycle is three NADH, one FADH2, and one GTP or ATP.', 'Wikipedia: Citric acid cycle', 'https://en.wikipedia.org/w/index.php?title=Citric_acid_cycle&oldid=1379847022', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Its name is derived from the citric acid (a tricarboxylic acid, often called citrate, as the ionized form predominates at biological pH) that is consumed and then regenerated by this sequence of reactions. The cycle consumes acetate (in the form of acetyl-CoA) and water and reduces NAD+ to NADH, releasing carbon dioxide. The NADH generated by the citric acid cycle is fed into the oxidative phosphorylation (electron transport) pathway. The net result of these two closely linked pathways is the oxidation of nutrients to produce usable chemical energy in the form of ATP. In eukaryotic cells, the citric acid cycle occurs in the mitochondrial matrix. In prokaryotic cells, such as bacteria, which lack mitochondria, the citric acid cycle reaction sequence is performed in the cytosol with the proton gradient for ATP production being across the cell''s surface (plasma membrane) rather than the inner membrane of the mitochondrion. For each pyruvate molecule (from glycolysis), the overall yield of energy-containing compounds from the citric acid cycle is three NADH, one FADH2, and one GTP or ATP.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Citric acid cycle: Discovery', 'Several of the components and reactions of the citric acid cycle were established in the 1930s by the research of Albert Szent-Györgyi, who received the Nobel Prize in Physiology or Medicine in 1937 specifically for his discoveries pertaining to fumaric acid, a component of the cycle. He made this discovery by studying pigeon breast muscle. Because this tissue maintains its oxidative capacity well after breaking down in the Latapie mincer and releasing in aqueous solutions, breast muscle of the pigeon was very well qualified for the study of oxidative reactions. The citric acid cycle itself was finally identified in 1937 by Hans Adolf Krebs and William Arthur Johnson while at the University of Sheffield, for which the former received the Nobel Prize for Physiology or Medicine in 1953, and for whom the cycle is sometimes named the "Krebs cycle". Independently citric acid cycle was identified in 1937 by German biochemists Carl Martius and Franz Knoop.', 'Wikipedia: Citric acid cycle', 'https://en.wikipedia.org/w/index.php?title=Citric_acid_cycle&oldid=1379847022', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Several of the components and reactions of the citric acid cycle were established in the 1930s by the research of Albert Szent-Györgyi, who received the Nobel Prize in Physiology or Medicine in 1937 specifically for his discoveries pertaining to fumaric acid, a component of the cycle. He made this discovery by studying pigeon breast muscle. Because this tissue maintains its oxidative capacity well after breaking down in the Latapie mincer and releasing in aqueous solutions, breast muscle of the pigeon was very well qualified for the study of oxidative reactions. The citric acid cycle itself was finally identified in 1937 by Hans Adolf Krebs and William Arthur Johnson while at the University of Sheffield, for which the former received the Nobel Prize for Physiology or Medicine in 1953, and for whom the cycle is sometimes named the "Krebs cycle". Independently citric acid cycle was identified in 1937 by German biochemists Carl Martius and Franz Knoop.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Citric acid cycle: Overview', 'The citric acid cycle is a metabolic pathway that connects carbohydrate, fat, and protein metabolism. The reactions of the cycle are carried out by eight enzymes that completely oxidize acetate (a two carbon molecule), in the form of acetyl-CoA, into two molecules each of carbon dioxide. Through catabolism of sugars, fats, and proteins, the two-carbon organic product acetyl-CoA is produced which enters the citric acid cycle. The reactions of the cycle also convert three equivalents of nicotinamide adenine dinucleotide (NAD+) into three equivalents of reduced NAD (NADH), one equivalent of flavin adenine dinucleotide (FAD) into one equivalent of FADH2, and one equivalent each of guanosine diphosphate (GDP) and inorganic phosphate (Pi) into one equivalent of guanosine triphosphate (GTP). The NADH and FADH2 generated by the citric acid cycle are, in turn, used by the oxidative phosphorylation pathway to generate energy-rich ATP. One of the primary sources of acetyl-CoA is from the breakdown of sugars by glycolysis which yield pyruvate that in turn is decarboxylated by the pyruvate dehydrogenase complex generating acetyl-CoA according to the following reaction scheme: The product of this reaction, acetyl-CoA, is the starting point for the citric acid cycle. Acetyl-CoA may also be obtained from the oxidation of fatty acids. Below is a schematic outline of the cycle:', 'Wikipedia: Citric acid cycle', 'https://en.wikipedia.org/w/index.php?title=Citric_acid_cycle&oldid=1379847022', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The citric acid cycle is a metabolic pathway that connects carbohydrate, fat, and protein metabolism. The reactions of the cycle are carried out by eight enzymes that completely oxidize acetate (a two carbon molecule), in the form of acetyl-CoA, into two molecules each of carbon dioxide. Through catabolism of sugars, fats, and proteins, the two-carbon organic product acetyl-CoA is produced which enters the citric acid cycle. The reactions of the cycle also convert three equivalents of nicotinamide adenine dinucleotide (NAD+) into three equivalents of reduced NAD (NADH), one equivalent of flavin adenine dinucleotide (FAD) into one equivalent of FADH2, and one equivalent each of guanosine diphosphate (GDP) and inorganic phosphate (Pi) into one equivalent of guanosine triphosphate (GTP). The NADH and FADH2 generated by the citric acid cycle are, in turn, used by the oxidative phosphorylation pathway to generate energy-rich ATP. One of the primary sources of acetyl-CoA is from the breakdown of sugars by glycolysis which yield pyruvate that in turn is decarboxylated by the pyruvate dehydrogenase complex generating acetyl-CoA according to the following reaction scheme: The product of this reaction, acetyl-CoA, is the starting point for the citric acid cycle. Acetyl-CoA may also be obtained from the oxidation of fatty acids. Below is a schematic outline of the cycle:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Citric acid cycle: Overview', 'The citric acid cycle begins with the transfer of a two-carbon acetyl group from acetyl-CoA to the four-carbon acceptor compound (oxaloacetate) to form a six-carbon compound (citrate). The citrate then goes through a series of chemical transformations, losing two carboxyl groups as CO2. The carbons lost as CO2 originate from what was oxaloacetate, not directly from acetyl-CoA. The carbons donated by acetyl-CoA become part of the oxaloacetate carbon backbone after the first turn of the citric acid cycle. Loss of the acetyl-CoA-donated carbons as CO2 requires several turns of the citric acid cycle. However, because of the role of the citric acid cycle in anabolism, they might not be lost, since many citric acid cycle intermediates are also used as precursors for the biosynthesis of other molecules. Most of the electrons made available by the oxidative steps of the cycle are transferred to NAD+, forming NADH. For each acetyl group that enters the citric acid cycle, three molecules of NADH are produced. The citric acid cycle includes a series of redox reactions in mitochondria.', 'Wikipedia: Citric acid cycle', 'https://en.wikipedia.org/w/index.php?title=Citric_acid_cycle&oldid=1379847022', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The citric acid cycle begins with the transfer of a two-carbon acetyl group from acetyl-CoA to the four-carbon acceptor compound (oxaloacetate) to form a six-carbon compound (citrate). The citrate then goes through a series of chemical transformations, losing two carboxyl groups as CO2. The carbons lost as CO2 originate from what was oxaloacetate, not directly from acetyl-CoA. The carbons donated by acetyl-CoA become part of the oxaloacetate carbon backbone after the first turn of the citric acid cycle. Loss of the acetyl-CoA-donated carbons as CO2 requires several turns of the citric acid cycle. However, because of the role of the citric acid cycle in anabolism, they might not be lost, since many citric acid cycle intermediates are also used as precursors for the biosynthesis of other molecules. Most of the electrons made available by the oxidative steps of the cycle are transferred to NAD+, forming NADH. For each acetyl group that enters the citric acid cycle, three molecules of NADH are produced. The citric acid cycle includes a series of redox reactions in mitochondria.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Citric acid cycle: Overview', 'In addition, electrons from the succinate oxidation step are transferred first to the FAD cofactor of succinate dehydrogenase, reducing it to FADH2, and eventually to ubiquinone (Q) in the mitochondrial membrane, reducing it to ubiquinol (QH2) which is a substrate of the electron transfer chain at the level of Complex III. For every NADH and FADH2 that are produced in the citric acid cycle, 2.5 and 1.5 ATP molecules are generated in oxidative phosphorylation, respectively. At the end of each cycle, the four-carbon oxaloacetate has been regenerated, and the cycle continues.', 'Wikipedia: Citric acid cycle', 'https://en.wikipedia.org/w/index.php?title=Citric_acid_cycle&oldid=1379847022', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'In addition, electrons from the succinate oxidation step are transferred first to the FAD cofactor of succinate dehydrogenase, reducing it to FADH2, and eventually to ubiquinone (Q) in the mitochondrial membrane, reducing it to ubiquinol (QH2) which is a substrate of the electron transfer chain at the level of Complex III. For every NADH and FADH2 that are produced in the citric acid cycle, 2.5 and 1.5 ATP molecules are generated in oxidative phosphorylation, respectively. At the end of each cycle, the four-carbon oxaloacetate has been regenerated, and the cycle continues.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Citric acid cycle: Steps', 'There are ten basic steps in the citric acid cycle, as outlined below. The cycle is continuously supplied with new carbon in the form of acetyl-CoA, entering at step 0 in the table. Two carbon atoms are oxidized to CO2, the energy from these reactions is transferred to other metabolic processes through GTP (or ATP), and as electrons in NADH and QH2. The NADH generated in the citric acid cycle may later be oxidized (donate its electrons) to drive ATP synthesis in a type of process called oxidative phosphorylation. FADH2 is covalently attached to succinate dehydrogenase, an enzyme which functions both in the citric acid cycle and the mitochondrial electron transport chain in oxidative phosphorylation. FADH2, therefore, facilitates transfer of electrons to coenzyme Q, which is the final electron acceptor of the reaction catalyzed by the succinate:ubiquinone oxidoreductase complex, also acting as an intermediate in the electron transport chain. Mitochondria in animal cells, possess two succinyl-CoA synthetases: one that produces GTP from GDP, and another that produces ATP from ADP. Plant cells have the type that produces ATP (ADP-forming succinyl-CoA synthetase). Several of the enzymes in the cycle may be loosely associated in a multienzyme protein complex within the mitochondrial matrix.', 'Wikipedia: Citric acid cycle', 'https://en.wikipedia.org/w/index.php?title=Citric_acid_cycle&oldid=1379847022', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'There are ten basic steps in the citric acid cycle, as outlined below. The cycle is continuously supplied with new carbon in the form of acetyl-CoA, entering at step 0 in the table. Two carbon atoms are oxidized to CO2, the energy from these reactions is transferred to other metabolic processes through GTP (or ATP), and as electrons in NADH and QH2. The NADH generated in the citric acid cycle may later be oxidized (donate its electrons) to drive ATP synthesis in a type of process called oxidative phosphorylation. FADH2 is covalently attached to succinate dehydrogenase, an enzyme which functions both in the citric acid cycle and the mitochondrial electron transport chain in oxidative phosphorylation. FADH2, therefore, facilitates transfer of electrons to coenzyme Q, which is the final electron acceptor of the reaction catalyzed by the succinate:ubiquinone oxidoreductase complex, also acting as an intermediate in the electron transport chain. Mitochondria in animal cells, possess two succinyl-CoA synthetases: one that produces GTP from GDP, and another that produces ATP from ADP. Plant cells have the type that produces ATP (ADP-forming succinyl-CoA synthetase). Several of the enzymes in the cycle may be loosely associated in a multienzyme protein complex within the mitochondrial matrix.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Citric acid cycle: Steps', 'The GTP that is formed by GDP-forming succinyl-CoA synthetase may be utilized by nucleoside-diphosphate kinase to form ATP (the catalyzed reaction is GTP + ADP → GDP + ATP).', 'Wikipedia: Citric acid cycle', 'https://en.wikipedia.org/w/index.php?title=Citric_acid_cycle&oldid=1379847022', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The GTP that is formed by GDP-forming succinyl-CoA synthetase may be utilized by nucleoside-diphosphate kinase to form ATP (the catalyzed reaction is GTP + ADP → GDP + ATP).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Oxidative phosphorylation', 'Oxidative phosphorylation or electron transport-linked phosphorylation or terminal oxidation, is the metabolic pathway in which cells use enzymes to oxidize nutrients, thereby releasing chemical energy in order to produce adenosine triphosphate (ATP). In eukaryotes, this takes place inside mitochondria. Almost all aerobic organisms carry out oxidative phosphorylation. This pathway is so pervasive because it releases more energy than fermentation. In aerobic respiration, the energy stored in the chemical bonds of glucose is released by the cell in glycolysis and subsequently the citric acid cycle, producing carbon dioxide and the energetic electron donors NADH and FADH₂. Oxidative phosphorylation uses these molecules and O2 to produce ATP, which is used throughout the cell whenever energy is needed. During oxidative phosphorylation, electrons are transferred from the electron donors to a series of electron acceptors in a series of redox reactions ending in oxygen, whose reaction releases half of the total energy. In eukaryotes, these redox reactions are catalyzed by a series of protein complexes within the inner mitochondrial membrane; whereas, in prokaryotes, these proteins are located in the cell''s plasma membrane. These linked sets of proteins are called the electron transport chain. In mitochondria, five main protein complexes are involved, whereas prokaryotes have various other enzymes, using a variety of electron donors and acceptors.', 'Wikipedia: Oxidative phosphorylation', 'https://en.wikipedia.org/w/index.php?title=Oxidative_phosphorylation&oldid=1368886692', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Oxidative phosphorylation or electron transport-linked phosphorylation or terminal oxidation, is the metabolic pathway in which cells use enzymes to oxidize nutrients, thereby releasing chemical energy in order to produce adenosine triphosphate (ATP). In eukaryotes, this takes place inside mitochondria. Almost all aerobic organisms carry out oxidative phosphorylation. This pathway is so pervasive because it releases more energy than fermentation. In aerobic respiration, the energy stored in the chemical bonds of glucose is released by the cell in glycolysis and subsequently the citric acid cycle, producing carbon dioxide and the energetic electron donors NADH and FADH₂. Oxidative phosphorylation uses these molecules and O2 to produce ATP, which is used throughout the cell whenever energy is needed. During oxidative phosphorylation, electrons are transferred from the electron donors to a series of electron acceptors in a series of redox reactions ending in oxygen, whose reaction releases half of the total energy. In eukaryotes, these redox reactions are catalyzed by a series of protein complexes within the inner mitochondrial membrane; whereas, in prokaryotes, these proteins are located in the cell''s plasma membrane. These linked sets of proteins are called the electron transport chain. In mitochondria, five main protein complexes are involved, whereas prokaryotes have various other enzymes, using a variety of electron donors and acceptors.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Oxidative phosphorylation', 'The energy transferred by electrons flowing through this electron transport chain is used to transport protons across the inner membrane. This generates potential energy in the form of a pH gradient and the resulting electrical potential across this membrane. This store of energy is tapped when protons flow back across the membrane through ATP synthase in a process called chemiosmosis. The ATP synthase uses the energy to transform adenosine diphosphate (ADP) into adenosine triphosphate, in a phosphorylation reaction. The reaction is driven by the proton flow, which forces the rotation of a part of the enzyme. The ATP synthase is a rotary mechanical motor. Although oxidative phosphorylation is a vital part of metabolism, it produces reactive oxygen species such as superoxide and hydrogen peroxide, which lead to propagation of free radicals, damaging cells and contributing to disease and, possibly, aging and senescence. The enzymes carrying out this metabolic pathway are also the target of many drugs and poisons that inhibit their activities.', 'Wikipedia: Oxidative phosphorylation', 'https://en.wikipedia.org/w/index.php?title=Oxidative_phosphorylation&oldid=1368886692', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The energy transferred by electrons flowing through this electron transport chain is used to transport protons across the inner membrane. This generates potential energy in the form of a pH gradient and the resulting electrical potential across this membrane. This store of energy is tapped when protons flow back across the membrane through ATP synthase in a process called chemiosmosis. The ATP synthase uses the energy to transform adenosine diphosphate (ADP) into adenosine triphosphate, in a phosphorylation reaction. The reaction is driven by the proton flow, which forces the rotation of a part of the enzyme. The ATP synthase is a rotary mechanical motor. Although oxidative phosphorylation is a vital part of metabolism, it produces reactive oxygen species such as superoxide and hydrogen peroxide, which lead to propagation of free radicals, damaging cells and contributing to disease and, possibly, aging and senescence. The enzymes carrying out this metabolic pathway are also the target of many drugs and poisons that inhibit their activities.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Oxidative phosphorylation: Chemiosmosis', 'Oxidative phosphorylation works by using energy-releasing chemical reactions to drive energy-requiring reactions. The two sets of reactions are said to be coupled. This means one cannot occur without the other. The chain of redox reactions driving the flow of electrons through the electron transport chain, from electron donors such as NADH to electron acceptors such as oxygen and hydrogen (protons), is an exergonic process – it releases energy, whereas the synthesis of ATP is an endergonic process, which requires an input of energy. Both the electron transport chain and the ATP synthase are embedded in a membrane, and energy is transferred from the electron transport chain to the ATP synthase by movements of protons across this membrane, in a process called chemiosmosis. A current of protons is driven from the negative N-side of the membrane to the positive P-side through the proton-pumping enzymes of the electron transport chain. The movement of protons creates an electrochemical gradient across the membrane, which is called the proton-motive force. It has two components: a difference in proton concentration (a H+ gradient, ΔpH) and a difference in electric potential, with the N-side having a negative charge.', 'Wikipedia: Oxidative phosphorylation', 'https://en.wikipedia.org/w/index.php?title=Oxidative_phosphorylation&oldid=1368886692', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Oxidative phosphorylation works by using energy-releasing chemical reactions to drive energy-requiring reactions. The two sets of reactions are said to be coupled. This means one cannot occur without the other. The chain of redox reactions driving the flow of electrons through the electron transport chain, from electron donors such as NADH to electron acceptors such as oxygen and hydrogen (protons), is an exergonic process – it releases energy, whereas the synthesis of ATP is an endergonic process, which requires an input of energy. Both the electron transport chain and the ATP synthase are embedded in a membrane, and energy is transferred from the electron transport chain to the ATP synthase by movements of protons across this membrane, in a process called chemiosmosis. A current of protons is driven from the negative N-side of the membrane to the positive P-side through the proton-pumping enzymes of the electron transport chain. The movement of protons creates an electrochemical gradient across the membrane, which is called the proton-motive force. It has two components: a difference in proton concentration (a H+ gradient, ΔpH) and a difference in electric potential, with the N-side having a negative charge.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Oxidative phosphorylation: Chemiosmosis', 'ATP synthase releases this stored energy by completing the circuit and allowing protons to flow down the electrochemical gradient, back to the N-side of the membrane. The electrochemical gradient drives the rotation of part of the enzyme''s structure and couples this motion to the synthesis of ATP. The two components of the proton-motive force are thermodynamically equivalent: In mitochondria, the largest part of energy is provided by the potential; in alkaliphile bacteria the electrical energy even has to compensate for a counteracting inverse pH difference. Inversely, chloroplasts operate mainly on ΔpH. However, they also require a small membrane potential for the kinetics of ATP synthesis. In the case of the fusobacterium Propionigenium modestum it drives the counter-rotation of subunits a and c of the FO motor of ATP synthase. The amount of energy released by oxidative phosphorylation is high, compared with the amount produced by fermentation. Glycolysis produces only 2 ATP molecules, but somewhere between 30 and 36 ATPs are produced by the oxidative phosphorylation of the 10 NADH and 2 succinate molecules made by converting one molecule of glucose to carbon dioxide and water, while each cycle of beta oxidation of a fatty acid yields about 14 ATPs. These ATP yields are theoretical maximum values; in practice, some protons leak across the membrane, lowering the yield of ATP.', 'Wikipedia: Oxidative phosphorylation', 'https://en.wikipedia.org/w/index.php?title=Oxidative_phosphorylation&oldid=1368886692', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'ATP synthase releases this stored energy by completing the circuit and allowing protons to flow down the electrochemical gradient, back to the N-side of the membrane. The electrochemical gradient drives the rotation of part of the enzyme''s structure and couples this motion to the synthesis of ATP. The two components of the proton-motive force are thermodynamically equivalent: In mitochondria, the largest part of energy is provided by the potential; in alkaliphile bacteria the electrical energy even has to compensate for a counteracting inverse pH difference. Inversely, chloroplasts operate mainly on ΔpH. However, they also require a small membrane potential for the kinetics of ATP synthesis. In the case of the fusobacterium Propionigenium modestum it drives the counter-rotation of subunits a and c of the FO motor of ATP synthase. The amount of energy released by oxidative phosphorylation is high, compared with the amount produced by fermentation. Glycolysis produces only 2 ATP molecules, but somewhere between 30 and 36 ATPs are produced by the oxidative phosphorylation of the 10 NADH and 2 succinate molecules made by converting one molecule of glucose to carbon dioxide and water, while each cycle of beta oxidation of a fatty acid yields about 14 ATPs. These ATP yields are theoretical maximum values; in practice, some protons leak across the membrane, lowering the yield of ATP.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Oxidative phosphorylation: Electron and proton transfer molecules', 'The electron transport chain carries both protons and electrons, passing electrons from donors to acceptors, and transporting protons across a membrane. These processes use both soluble and protein-bound transfer molecules. In the mitochondria, electrons are transferred within the intermembrane space by the water-soluble electron transfer protein cytochrome c. This carries only electrons, and these are transferred by the reduction and oxidation of an iron atom that the protein holds within a heme group in its structure. Cytochrome c is also found in some bacteria, where it is located within the periplasmic space. Within the inner mitochondrial membrane, the lipid-soluble electron carrier coenzyme Q10 (Q) carries both electrons and protons by a redox cycle. This small benzoquinone molecule is very hydrophobic, so it diffuses freely within the membrane. When Q accepts two electrons and two protons, it becomes reduced to the ubiquinol form (QH2); when QH2 releases two electrons and two protons, it becomes oxidized back to the ubiquinone (Q) form. As a result, if two enzymes are arranged so that Q is reduced on one side of the membrane and QH2 oxidized on the other, ubiquinone will couple these reactions and shuttle protons across the membrane. Some bacterial electron transport chains use different quinones, such as menaquinone, in addition to ubiquinone.', 'Wikipedia: Oxidative phosphorylation', 'https://en.wikipedia.org/w/index.php?title=Oxidative_phosphorylation&oldid=1368886692', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The electron transport chain carries both protons and electrons, passing electrons from donors to acceptors, and transporting protons across a membrane. These processes use both soluble and protein-bound transfer molecules. In the mitochondria, electrons are transferred within the intermembrane space by the water-soluble electron transfer protein cytochrome c. This carries only electrons, and these are transferred by the reduction and oxidation of an iron atom that the protein holds within a heme group in its structure. Cytochrome c is also found in some bacteria, where it is located within the periplasmic space. Within the inner mitochondrial membrane, the lipid-soluble electron carrier coenzyme Q10 (Q) carries both electrons and protons by a redox cycle. This small benzoquinone molecule is very hydrophobic, so it diffuses freely within the membrane. When Q accepts two electrons and two protons, it becomes reduced to the ubiquinol form (QH2); when QH2 releases two electrons and two protons, it becomes oxidized back to the ubiquinone (Q) form. As a result, if two enzymes are arranged so that Q is reduced on one side of the membrane and QH2 oxidized on the other, ubiquinone will couple these reactions and shuttle protons across the membrane. Some bacterial electron transport chains use different quinones, such as menaquinone, in addition to ubiquinone.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Oxidative phosphorylation: Electron and proton transfer molecules', 'Within proteins, electrons are transferred between flavin cofactors, iron–sulfur clusters and cytochromes. There are several types of iron–sulfur cluster. The simplest kind found in the electron transfer chain consists of two iron atoms joined by two atoms of inorganic sulfur; these are called [2Fe–2S] clusters. The second kind, called [4Fe–4S], contains a cube of four iron atoms and four sulfur atoms. Each iron atom in these clusters is coordinated by an additional amino acid, usually by the sulfur atom of cysteine. Metal ion cofactors undergo redox reactions without binding or releasing protons, so in the electron transport chain they serve solely to transport electrons through proteins. Electrons move quite long distances through proteins by hopping along chains of these cofactors. This occurs by quantum tunnelling, which is rapid over distances of less than 1.4×10−9 m.', 'Wikipedia: Oxidative phosphorylation', 'https://en.wikipedia.org/w/index.php?title=Oxidative_phosphorylation&oldid=1368886692', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Within proteins, electrons are transferred between flavin cofactors, iron–sulfur clusters and cytochromes. There are several types of iron–sulfur cluster. The simplest kind found in the electron transfer chain consists of two iron atoms joined by two atoms of inorganic sulfur; these are called [2Fe–2S] clusters. The second kind, called [4Fe–4S], contains a cube of four iron atoms and four sulfur atoms. Each iron atom in these clusters is coordinated by an additional amino acid, usually by the sulfur atom of cysteine. Metal ion cofactors undergo redox reactions without binding or releasing protons, so in the electron transport chain they serve solely to transport electrons through proteins. Electrons move quite long distances through proteins by hopping along chains of these cofactors. This occurs by quantum tunnelling, which is rapid over distances of less than 1.4×10−9 m.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Oxidative phosphorylation: Eukaryotic electron transport chains', 'Many catabolic biochemical processes, such as glycolysis, the citric acid cycle, and beta oxidation, produce the reduced coenzyme NADH. This coenzyme contains electrons that have a high transfer potential; in other words, they will release a large amount of energy upon oxidation. However, the cell does not release this energy all at once, as this would be an uncontrollable reaction. Instead, the electrons are removed from NADH and passed to oxygen through a series of enzymes that each release a small amount of the energy. This set of enzymes, consisting of complexes I through IV, is called the electron transport chain and is found in the inner membrane of the mitochondrion. In eukaryotes, the enzymes in this electron transport system use the energy released from O2 by NADH to pump protons across the inner membrane of the mitochondrion. This causes protons to build up in the intermembrane space, and generates an electrochemical gradient across the membrane. The energy stored in this potential is then used by ATP synthase to produce ATP. Oxidative phosphorylation in the eukaryotic mitochondrion is the best-understood example of this process. The mitochondrion is present in almost all eukaryotes, with the exception of anaerobic protozoa such as Trichomonas vaginalis that instead reduce protons to hydrogen in a remnant mitochondrion called a hydrogenosome.', 'Wikipedia: Oxidative phosphorylation', 'https://en.wikipedia.org/w/index.php?title=Oxidative_phosphorylation&oldid=1368886692', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Many catabolic biochemical processes, such as glycolysis, the citric acid cycle, and beta oxidation, produce the reduced coenzyme NADH. This coenzyme contains electrons that have a high transfer potential; in other words, they will release a large amount of energy upon oxidation. However, the cell does not release this energy all at once, as this would be an uncontrollable reaction. Instead, the electrons are removed from NADH and passed to oxygen through a series of enzymes that each release a small amount of the energy. This set of enzymes, consisting of complexes I through IV, is called the electron transport chain and is found in the inner membrane of the mitochondrion. In eukaryotes, the enzymes in this electron transport system use the energy released from O2 by NADH to pump protons across the inner membrane of the mitochondrion. This causes protons to build up in the intermembrane space, and generates an electrochemical gradient across the membrane. The energy stored in this potential is then used by ATP synthase to produce ATP. Oxidative phosphorylation in the eukaryotic mitochondrion is the best-understood example of this process. The mitochondrion is present in almost all eukaryotes, with the exception of anaerobic protozoa such as Trichomonas vaginalis that instead reduce protons to hydrogen in a remnant mitochondrion called a hydrogenosome.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Oxidative phosphorylation: NADH-coenzyme Q oxidoreductase (complex I)', 'NADH-coenzyme Q oxidoreductase, also known as NADH dehydrogenase or complex I, is the first protein in the electron transport chain. Complex I is a giant enzyme with the mammalian complex I having 46 subunits and a molecular mass of about 1000 kDa. The structure is known in detail only from a bacterium; in most organisms the complex resembles a boot with a large "ball" poking out from the membrane into the mitochondrion. The genes that encode the individual proteins are contained in both the cell nucleus and the mitochondrial genome, as is the case for many enzymes present in the mitochondrion. The reaction that is catalyzed by this enzyme is the two electron oxidation of NADH by coenzyme Q10 or ubiquinone (represented as Q in the equation below), a lipid-soluble quinone that is found in the mitochondrion membrane:', 'Wikipedia: Oxidative phosphorylation', 'https://en.wikipedia.org/w/index.php?title=Oxidative_phosphorylation&oldid=1368886692', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'NADH-coenzyme Q oxidoreductase, also known as NADH dehydrogenase or complex I, is the first protein in the electron transport chain. Complex I is a giant enzyme with the mammalian complex I having 46 subunits and a molecular mass of about 1000 kDa. The structure is known in detail only from a bacterium; in most organisms the complex resembles a boot with a large "ball" poking out from the membrane into the mitochondrion. The genes that encode the individual proteins are contained in both the cell nucleus and the mitochondrial genome, as is the case for many enzymes present in the mitochondrion. The reaction that is catalyzed by this enzyme is the two electron oxidation of NADH by coenzyme Q10 or ubiquinone (represented as Q in the equation below), a lipid-soluble quinone that is found in the mitochondrion membrane:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Gluconeogenesis', 'Gluconeogenesis (GNG) is a metabolic pathway that results in the biosynthesis of glucose from certain non-carbohydrate carbon substrates. It is a ubiquitous process, present in plants, animals, fungi, bacteria, and other microorganisms. In vertebrates, gluconeogenesis occurs mainly in the liver and, to a lesser extent, in the cortex of the kidneys. It is one of two primary mechanisms – the other being degradation of glycogen (glycogenolysis) – used by humans and many other animals to maintain blood sugar levels, avoiding low levels (hypoglycemia). In ruminants, because dietary carbohydrates tend to be metabolized by rumen organisms, gluconeogenesis occurs regardless of fasting, low-carbohydrate diets, exercise, etc. In many other animals, the process occurs during periods of fasting, starvation, low-carbohydrate diets, or intense exercise.', 'Wikipedia: Gluconeogenesis', 'https://en.wikipedia.org/w/index.php?title=Gluconeogenesis&oldid=1374881012', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Gluconeogenesis (GNG) is a metabolic pathway that results in the biosynthesis of glucose from certain non-carbohydrate carbon substrates. It is a ubiquitous process, present in plants, animals, fungi, bacteria, and other microorganisms. In vertebrates, gluconeogenesis occurs mainly in the liver and, to a lesser extent, in the cortex of the kidneys. It is one of two primary mechanisms – the other being degradation of glycogen (glycogenolysis) – used by humans and many other animals to maintain blood sugar levels, avoiding low levels (hypoglycemia). In ruminants, because dietary carbohydrates tend to be metabolized by rumen organisms, gluconeogenesis occurs regardless of fasting, low-carbohydrate diets, exercise, etc. In many other animals, the process occurs during periods of fasting, starvation, low-carbohydrate diets, or intense exercise.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Gluconeogenesis', 'In humans, substrates for gluconeogenesis may come from any non-carbohydrate sources that can be converted to pyruvate or intermediates of glycolysis (see figure). From the breakdown of proteins, these substrates include glucogenic amino acids (although not ketogenic amino acids); from breakdown of lipids (such as triglycerides), they include glycerol, odd-chain fatty acids (although not even-chain fatty acids, see below); and from other parts of metabolism that includes lactate from the Cori cycle. Under conditions of prolonged fasting, acetone derived from ketone bodies could potentially also serve as a substrate based on computer models. This could provide a pathway from fatty acids to glucose, but whether this actually happens in the human body is controversial. Although most gluconeogenesis occurs in the liver, the relative contribution of gluconeogenesis by the kidney is increased in diabetes and prolonged fasting. The gluconeogenesis pathway is highly endergonic until it is coupled to the hydrolysis of ATP or GTP, effectively making the process exergonic. For example, the pathway leading from pyruvate to glucose-6-phosphate requires 4 molecules of ATP and 2 molecules of GTP to proceed spontaneously. These ATPs are supplied from fatty acid catabolism via beta oxidation.', 'Wikipedia: Gluconeogenesis', 'https://en.wikipedia.org/w/index.php?title=Gluconeogenesis&oldid=1374881012', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'In humans, substrates for gluconeogenesis may come from any non-carbohydrate sources that can be converted to pyruvate or intermediates of glycolysis (see figure). From the breakdown of proteins, these substrates include glucogenic amino acids (although not ketogenic amino acids); from breakdown of lipids (such as triglycerides), they include glycerol, odd-chain fatty acids (although not even-chain fatty acids, see below); and from other parts of metabolism that includes lactate from the Cori cycle. Under conditions of prolonged fasting, acetone derived from ketone bodies could potentially also serve as a substrate based on computer models. This could provide a pathway from fatty acids to glucose, but whether this actually happens in the human body is controversial. Although most gluconeogenesis occurs in the liver, the relative contribution of gluconeogenesis by the kidney is increased in diabetes and prolonged fasting. The gluconeogenesis pathway is highly endergonic until it is coupled to the hydrolysis of ATP or GTP, effectively making the process exergonic. For example, the pathway leading from pyruvate to glucose-6-phosphate requires 4 molecules of ATP and 2 molecules of GTP to proceed spontaneously. These ATPs are supplied from fatty acid catabolism via beta oxidation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Gluconeogenesis: Precursors', 'In humans the main gluconeogenic precursors are lactate, glycerol (which is a part of the triglyceride molecule), alanine and glutamine. Altogether, they account for over 90% of the overall gluconeogenesis. Other glucogenic amino acids and all citric acid cycle intermediates (through conversion to oxaloacetate) can also function as substrates for gluconeogenesis. Generally, human consumption of gluconeogenic substrates in food does not result in increased gluconeogenesis. In ruminants, propionate is the principal gluconeogenic substrate. In nonruminants, including human beings, propionate arises from the β-oxidation of odd-chain and branched-chain fatty acids, and is a (relatively minor) substrate for gluconeogenesis. Lactate is transported back to the liver where it is converted into pyruvate by the Cori cycle using the enzyme lactate dehydrogenase. Pyruvate, the first designated substrate of the gluconeogenic pathway, can then be used to generate glucose. Transamination or deamination of amino acids facilitates entering of their carbon skeleton into the cycle directly (as pyruvate or oxaloacetate), or indirectly via the citric acid cycle. The contribution of Cori cycle lactate to overall glucose production increases with fasting duration. Specifically, after 12, 20, and 40 hours of fasting by human volunteers, the contribution of Cori cycle lactate to gluconeogenesis was 41%, 71%, and 92%, respectively.', 'Wikipedia: Gluconeogenesis', 'https://en.wikipedia.org/w/index.php?title=Gluconeogenesis&oldid=1374881012', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'In humans the main gluconeogenic precursors are lactate, glycerol (which is a part of the triglyceride molecule), alanine and glutamine. Altogether, they account for over 90% of the overall gluconeogenesis. Other glucogenic amino acids and all citric acid cycle intermediates (through conversion to oxaloacetate) can also function as substrates for gluconeogenesis. Generally, human consumption of gluconeogenic substrates in food does not result in increased gluconeogenesis. In ruminants, propionate is the principal gluconeogenic substrate. In nonruminants, including human beings, propionate arises from the β-oxidation of odd-chain and branched-chain fatty acids, and is a (relatively minor) substrate for gluconeogenesis. Lactate is transported back to the liver where it is converted into pyruvate by the Cori cycle using the enzyme lactate dehydrogenase. Pyruvate, the first designated substrate of the gluconeogenic pathway, can then be used to generate glucose. Transamination or deamination of amino acids facilitates entering of their carbon skeleton into the cycle directly (as pyruvate or oxaloacetate), or indirectly via the citric acid cycle. The contribution of Cori cycle lactate to overall glucose production increases with fasting duration. Specifically, after 12, 20, and 40 hours of fasting by human volunteers, the contribution of Cori cycle lactate to gluconeogenesis was 41%, 71%, and 92%, respectively.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Gluconeogenesis: Precursors', 'Whether even-chain fatty acids can be converted into glucose in animals has been a longstanding question in biochemistry. Odd-chain fatty acids can be oxidized to yield acetyl-CoA and propionyl-CoA, the latter serving as a precursor to succinyl-CoA, which can be converted to oxaloacetate and enter into gluconeogenesis. In contrast, even-chain fatty acids are oxidized to yield only acetyl-CoA, whose entry into gluconeogenesis requires the presence of a glyoxylate cycle (also known as glyoxylate shunt) to produce four-carbon dicarboxylic acid precursors. The glyoxylate shunt comprises two enzymes, malate synthase and isocitrate lyase, and is present in fungi, plants, and bacteria. Despite some reports of glyoxylate shunt enzymatic activities detected in animal tissues, genes encoding both enzymatic functions have only been found in nematodes, in which they exist as a single bi-functional enzyme. Genes coding for malate synthase alone (but not isocitrate lyase) have been identified in other animals including arthropods, echinoderms, and even some vertebrates. Mammals found to possess the malate synthase gene include monotremes (platypus) and marsupials (opossum), but not placental mammals.', 'Wikipedia: Gluconeogenesis', 'https://en.wikipedia.org/w/index.php?title=Gluconeogenesis&oldid=1374881012', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Whether even-chain fatty acids can be converted into glucose in animals has been a longstanding question in biochemistry. Odd-chain fatty acids can be oxidized to yield acetyl-CoA and propionyl-CoA, the latter serving as a precursor to succinyl-CoA, which can be converted to oxaloacetate and enter into gluconeogenesis. In contrast, even-chain fatty acids are oxidized to yield only acetyl-CoA, whose entry into gluconeogenesis requires the presence of a glyoxylate cycle (also known as glyoxylate shunt) to produce four-carbon dicarboxylic acid precursors. The glyoxylate shunt comprises two enzymes, malate synthase and isocitrate lyase, and is present in fungi, plants, and bacteria. Despite some reports of glyoxylate shunt enzymatic activities detected in animal tissues, genes encoding both enzymatic functions have only been found in nematodes, in which they exist as a single bi-functional enzyme. Genes coding for malate synthase alone (but not isocitrate lyase) have been identified in other animals including arthropods, echinoderms, and even some vertebrates. Mammals found to possess the malate synthase gene include monotremes (platypus) and marsupials (opossum), but not placental mammals.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Gluconeogenesis: Precursors', 'The existence of the glyoxylate cycle in humans has not been established, and it is widely held that fatty acids cannot be converted to glucose in humans directly. Carbon-14 has been shown to end up in glucose when it is supplied in fatty acids, but this can be expected from the incorporation of labelled atoms derived from acetyl-CoA into citric acid cycle intermediates which are interchangeable with those derived from other physiological sources, such as glucogenic amino acids. In the absence of other glucogenic sources, the 2-carbon acetyl-CoA derived from the oxidation of fatty acids cannot produce a net yield of glucose via the citric acid cycle, since an equivalent two carbon atoms are released as carbon dioxide during the cycle. During ketosis, however, acetyl-CoA from fatty acids yields ketone bodies, including acetone, and up to ~60% of acetone may be oxidized in the liver to the pyruvate precursors acetol and methylglyoxal. Thus ketone bodies derived from fatty acids could account for up to 11% of gluconeogenesis during starvation. Catabolism of fatty acids also produces energy in the form of ATP that is necessary for the gluconeogenesis pathway.', 'Wikipedia: Gluconeogenesis', 'https://en.wikipedia.org/w/index.php?title=Gluconeogenesis&oldid=1374881012', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The existence of the glyoxylate cycle in humans has not been established, and it is widely held that fatty acids cannot be converted to glucose in humans directly. Carbon-14 has been shown to end up in glucose when it is supplied in fatty acids, but this can be expected from the incorporation of labelled atoms derived from acetyl-CoA into citric acid cycle intermediates which are interchangeable with those derived from other physiological sources, such as glucogenic amino acids. In the absence of other glucogenic sources, the 2-carbon acetyl-CoA derived from the oxidation of fatty acids cannot produce a net yield of glucose via the citric acid cycle, since an equivalent two carbon atoms are released as carbon dioxide during the cycle. During ketosis, however, acetyl-CoA from fatty acids yields ketone bodies, including acetone, and up to ~60% of acetone may be oxidized in the liver to the pyruvate precursors acetol and methylglyoxal. Thus ketone bodies derived from fatty acids could account for up to 11% of gluconeogenesis during starvation. Catabolism of fatty acids also produces energy in the form of ATP that is necessary for the gluconeogenesis pathway.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Gluconeogenesis: Bodily location', 'In mammals, gluconeogenesis has been believed to be restricted to the liver, the kidney, the intestine, and muscle, but recent evidence indicates gluconeogenesis occurring in astrocytes of the brain. These organs use somewhat different gluconeogenic precursors. The liver preferentially uses lactate, glycerol, and glucogenic amino acids (especially alanine) while the kidney preferentially uses lactate, glutamine and glycerol. Lactate from the Cori cycle is quantitatively the largest source of substrate for gluconeogenesis, especially for the kidney. The liver uses both glycogenolysis and gluconeogenesis to produce glucose, whereas the kidney only uses gluconeogenesis. After a meal, the liver shifts to glycogen synthesis, whereas the kidney increases gluconeogenesis. The intestine uses mostly glutamine and glycerol. Propionate is the principal substrate for gluconeogenesis in the ruminant liver, and the ruminant liver may make increased use of gluconeogenic amino acids (e.g., alanine) when glucose demand is increased. The capacity of liver cells to use lactate for gluconeogenesis declines from the preruminant stage to the ruminant stage in calves and lambs. In sheep kidney tissue, very high rates of gluconeogenesis from propionate have been observed.', 'Wikipedia: Gluconeogenesis', 'https://en.wikipedia.org/w/index.php?title=Gluconeogenesis&oldid=1374881012', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'In mammals, gluconeogenesis has been believed to be restricted to the liver, the kidney, the intestine, and muscle, but recent evidence indicates gluconeogenesis occurring in astrocytes of the brain. These organs use somewhat different gluconeogenic precursors. The liver preferentially uses lactate, glycerol, and glucogenic amino acids (especially alanine) while the kidney preferentially uses lactate, glutamine and glycerol. Lactate from the Cori cycle is quantitatively the largest source of substrate for gluconeogenesis, especially for the kidney. The liver uses both glycogenolysis and gluconeogenesis to produce glucose, whereas the kidney only uses gluconeogenesis. After a meal, the liver shifts to glycogen synthesis, whereas the kidney increases gluconeogenesis. The intestine uses mostly glutamine and glycerol. Propionate is the principal substrate for gluconeogenesis in the ruminant liver, and the ruminant liver may make increased use of gluconeogenic amino acids (e.g., alanine) when glucose demand is increased. The capacity of liver cells to use lactate for gluconeogenesis declines from the preruminant stage to the ruminant stage in calves and lambs. In sheep kidney tissue, very high rates of gluconeogenesis from propionate have been observed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Gluconeogenesis: Bodily location', 'In all species, the formation of oxaloacetate from pyruvate and TCA cycle intermediates is restricted to the mitochondrion, and the enzymes that convert phosphoenolpyruvic acid (PEP) to glucose-6-phosphate are found in the cytosol. The location of the enzyme that links these two parts of gluconeogenesis by converting oxaloacetate to PEP – PEP carboxykinase (PEPCK) – is variable by species: it can be found entirely within the mitochondria, entirely within the cytosol, or dispersed evenly between the two, as it is in humans. Transport of PEP across the mitochondrial membrane is accomplished by dedicated transport proteins; however no such proteins exist for oxaloacetate. Therefore, in species that lack intra-mitochondrial PEPCK, oxaloacetate must be converted into malate or aspartate, exported from the mitochondrion, and converted back into oxaloacetate in order to allow gluconeogenesis to continue.', 'Wikipedia: Gluconeogenesis', 'https://en.wikipedia.org/w/index.php?title=Gluconeogenesis&oldid=1374881012', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'In all species, the formation of oxaloacetate from pyruvate and TCA cycle intermediates is restricted to the mitochondrion, and the enzymes that convert phosphoenolpyruvic acid (PEP) to glucose-6-phosphate are found in the cytosol. The location of the enzyme that links these two parts of gluconeogenesis by converting oxaloacetate to PEP – PEP carboxykinase (PEPCK) – is variable by species: it can be found entirely within the mitochondria, entirely within the cytosol, or dispersed evenly between the two, as it is in humans. Transport of PEP across the mitochondrial membrane is accomplished by dedicated transport proteins; however no such proteins exist for oxaloacetate. Therefore, in species that lack intra-mitochondrial PEPCK, oxaloacetate must be converted into malate or aspartate, exported from the mitochondrion, and converted back into oxaloacetate in order to allow gluconeogenesis to continue.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Gluconeogenesis: Pathway', 'Gluconeogenesis is a pathway consisting of a series of eleven enzyme-catalyzed reactions. The pathway will begin in either the liver or kidney, in the mitochondria or cytoplasm of those cells, this being dependent on the substrate being used. Many of the reactions are the reverse of steps found in glycolysis. Gluconeogenesis begins in the mitochondria with the formation of oxaloacetate by the carboxylation of pyruvate. This reaction also requires one molecule of ATP, and is catalyzed by pyruvate carboxylase. This enzyme is stimulated by high levels of acetyl-CoA (produced in β-oxidation in the liver) and inhibited by high levels of ADP and glucose. Oxaloacetate is reduced to malate using NADH, a step required for its transportation out of the mitochondria. Malate is oxidized to oxaloacetate using NAD+ in the cytosol, where the remaining steps of gluconeogenesis take place. Oxaloacetate is decarboxylated and then phosphorylated to form phosphoenolpyruvate using the enzyme PEPCK. A molecule of GTP is hydrolyzed to GDP during this reaction. The next steps in the reaction are the same as reversed glycolysis. However, fructose 1,6-bisphosphatase converts fructose 1,6-bisphosphate to fructose 6-phosphate, using one water molecule and releasing one phosphate (in glycolysis, phosphofructokinase 1 converts F6P and ATP to F1,6BP and ADP). This is also the rate-limiting step of gluconeogenesis.', 'Wikipedia: Gluconeogenesis', 'https://en.wikipedia.org/w/index.php?title=Gluconeogenesis&oldid=1374881012', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Gluconeogenesis is a pathway consisting of a series of eleven enzyme-catalyzed reactions. The pathway will begin in either the liver or kidney, in the mitochondria or cytoplasm of those cells, this being dependent on the substrate being used. Many of the reactions are the reverse of steps found in glycolysis. Gluconeogenesis begins in the mitochondria with the formation of oxaloacetate by the carboxylation of pyruvate. This reaction also requires one molecule of ATP, and is catalyzed by pyruvate carboxylase. This enzyme is stimulated by high levels of acetyl-CoA (produced in β-oxidation in the liver) and inhibited by high levels of ADP and glucose. Oxaloacetate is reduced to malate using NADH, a step required for its transportation out of the mitochondria. Malate is oxidized to oxaloacetate using NAD+ in the cytosol, where the remaining steps of gluconeogenesis take place. Oxaloacetate is decarboxylated and then phosphorylated to form phosphoenolpyruvate using the enzyme PEPCK. A molecule of GTP is hydrolyzed to GDP during this reaction. The next steps in the reaction are the same as reversed glycolysis. However, fructose 1,6-bisphosphatase converts fructose 1,6-bisphosphate to fructose 6-phosphate, using one water molecule and releasing one phosphate (in glycolysis, phosphofructokinase 1 converts F6P and ATP to F1,6BP and ADP). This is also the rate-limiting step of gluconeogenesis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Beta oxidation', 'In biochemistry and metabolism, beta oxidation (also β-oxidation) is the catabolic process by which fatty acid molecules are broken down in the cytosol in prokaryotes and in the mitochondria in eukaryotes to generate acetyl-CoA. The acetyl-CoA product of this step of fatty acid metabolism enters the citric acid cycle, generating NADH and FADH2, which are electron carriers used in the electron transport chain. It is named as such because the beta carbon of the fatty acid chain undergoes oxidation and is converted to a carbonyl group to start the cycle all over again. Beta-oxidation is primarily facilitated by the mitochondrial trifunctional protein, an enzyme complex associated with the inner mitochondrial membrane, although very long chain fatty acids are oxidized in peroxisomes. Beta oxidation occurs mainly in the heart, liver and kidney. Cn-acyl-CoA + FAD + NAD+ + H2O + CoA → Cn-2-acyl-CoA + FADH2 + NADH + H+ + acetyl-CoA', 'Wikipedia: Beta oxidation', 'https://en.wikipedia.org/w/index.php?title=Beta_oxidation&oldid=1343709246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'In biochemistry and metabolism, beta oxidation (also β-oxidation) is the catabolic process by which fatty acid molecules are broken down in the cytosol in prokaryotes and in the mitochondria in eukaryotes to generate acetyl-CoA. The acetyl-CoA product of this step of fatty acid metabolism enters the citric acid cycle, generating NADH and FADH2, which are electron carriers used in the electron transport chain. It is named as such because the beta carbon of the fatty acid chain undergoes oxidation and is converted to a carbonyl group to start the cycle all over again. Beta-oxidation is primarily facilitated by the mitochondrial trifunctional protein, an enzyme complex associated with the inner mitochondrial membrane, although very long chain fatty acids are oxidized in peroxisomes. Beta oxidation occurs mainly in the heart, liver and kidney. Cn-acyl-CoA + FAD + NAD+ + H2O + CoA → Cn-2-acyl-CoA + FADH2 + NADH + H+ + acetyl-CoA');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Beta oxidation: Activation and membrane transport', 'Free fatty acids cannot penetrate any biological membrane due to their negative charge. Free fatty acids must cross the cell membrane through specific transport proteins, such as the SLC27 family fatty acid transport protein. Once in the cytosol, the following processes bring fatty acids into the mitochondrial matrix so that beta-oxidation can take place. Long-chain-fatty-acid—CoA ligase catalyzes the reaction between a fatty acid with ATP to give a fatty acyl adenylate, plus inorganic pyrophosphate, which then reacts with free coenzyme A to give a fatty acyl-CoA ester and AMP. If the fatty acyl-CoA has a long chain, then the carnitine shuttle must be utilized (shown in the table below): Acyl-CoA is transferred to the hydroxyl group of carnitine by carnitine palmitoyltransferase I, located on the cytosolic faces of the outer and inner mitochondrial membranes. Acyl-carnitine is shuttled inside by a carnitine-acylcarnitine translocase, as a carnitine is shuttled outside. Acyl-carnitine is converted back to acyl-CoA by carnitine palmitoyltransferase II, located on the interior face of the inner mitochondrial membrane. The liberated carnitine is shuttled back to the cytosol, as an acyl-carnitine is shuttled into the matrix. If the fatty acyl-CoA contains a short chain, these short-chain fatty acids can simply diffuse through the inner mitochondrial membrane.', 'Wikipedia: Beta oxidation', 'https://en.wikipedia.org/w/index.php?title=Beta_oxidation&oldid=1343709246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Free fatty acids cannot penetrate any biological membrane due to their negative charge. Free fatty acids must cross the cell membrane through specific transport proteins, such as the SLC27 family fatty acid transport protein. Once in the cytosol, the following processes bring fatty acids into the mitochondrial matrix so that beta-oxidation can take place. Long-chain-fatty-acid—CoA ligase catalyzes the reaction between a fatty acid with ATP to give a fatty acyl adenylate, plus inorganic pyrophosphate, which then reacts with free coenzyme A to give a fatty acyl-CoA ester and AMP. If the fatty acyl-CoA has a long chain, then the carnitine shuttle must be utilized (shown in the table below): Acyl-CoA is transferred to the hydroxyl group of carnitine by carnitine palmitoyltransferase I, located on the cytosolic faces of the outer and inner mitochondrial membranes. Acyl-carnitine is shuttled inside by a carnitine-acylcarnitine translocase, as a carnitine is shuttled outside. Acyl-carnitine is converted back to acyl-CoA by carnitine palmitoyltransferase II, located on the interior face of the inner mitochondrial membrane. The liberated carnitine is shuttled back to the cytosol, as an acyl-carnitine is shuttled into the matrix. If the fatty acyl-CoA contains a short chain, these short-chain fatty acids can simply diffuse through the inner mitochondrial membrane.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Beta oxidation: General mechanism of beta oxidation', 'Once the fatty acid is inside the mitochondrial matrix, beta-oxidation occurs by cleaving two carbons every cycle to form acetyl-CoA. The process consists of 4 steps. A long-chain fatty acid is dehydrogenated to create a trans double bond between C2 and C3. This is catalyzed by acyl CoA dehydrogenase to produce trans-delta 2-enoyl CoA. It uses FAD as an electron acceptor and it is reduced to FADH2. Trans-delta 2-enoyl CoA is hydrated at the double bond to produce L-3-hydroxyacyl CoA by enoyl-CoA hydratase. L-3-hydroxyacyl CoA is dehydrogenated again to create 3-ketoacyl CoA by 3-hydroxyacyl CoA dehydrogenase. This enzyme uses NAD as an electron acceptor. Thiolysis occurs between C2 and C3 (alpha and beta carbons) of 3-ketoacyl CoA. Thiolase enzyme catalyzes the reaction when a new molecule of coenzyme A breaks the bond by nucleophilic attack on C3. This releases the first two carbon units, as acetyl CoA, and a fatty acyl CoA minus two carbons. The process continues until all of the carbons in the fatty acid are turned into acetyl CoA. This acetyl-CoA then enters the mitochondrial tricarboxylic acid cycle (TCA cycle). Both the fatty acid beta-oxidation and the TCA cycle produce NADH and FADH2, which are used by the electron transport chain to generate ATP.', 'Wikipedia: Beta oxidation', 'https://en.wikipedia.org/w/index.php?title=Beta_oxidation&oldid=1343709246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Once the fatty acid is inside the mitochondrial matrix, beta-oxidation occurs by cleaving two carbons every cycle to form acetyl-CoA. The process consists of 4 steps. A long-chain fatty acid is dehydrogenated to create a trans double bond between C2 and C3. This is catalyzed by acyl CoA dehydrogenase to produce trans-delta 2-enoyl CoA. It uses FAD as an electron acceptor and it is reduced to FADH2. Trans-delta 2-enoyl CoA is hydrated at the double bond to produce L-3-hydroxyacyl CoA by enoyl-CoA hydratase. L-3-hydroxyacyl CoA is dehydrogenated again to create 3-ketoacyl CoA by 3-hydroxyacyl CoA dehydrogenase. This enzyme uses NAD as an electron acceptor. Thiolysis occurs between C2 and C3 (alpha and beta carbons) of 3-ketoacyl CoA. Thiolase enzyme catalyzes the reaction when a new molecule of coenzyme A breaks the bond by nucleophilic attack on C3. This releases the first two carbon units, as acetyl CoA, and a fatty acyl CoA minus two carbons. The process continues until all of the carbons in the fatty acid are turned into acetyl CoA. This acetyl-CoA then enters the mitochondrial tricarboxylic acid cycle (TCA cycle). Both the fatty acid beta-oxidation and the TCA cycle produce NADH and FADH2, which are used by the electron transport chain to generate ATP.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Beta oxidation: General mechanism of beta oxidation', 'Fatty acids are oxidized by most of the tissues in the body. However, some tissues such as the red blood cells of mammals (which do not contain mitochondria) and cells of the central nervous system do not use fatty acids for their energy requirements, but instead use carbohydrates (red blood cells and neurons) or ketone bodies (neurons only). Because many fatty acids are not fully saturated or do not have an even number of carbons, several different mechanisms have evolved, described below.', 'Wikipedia: Beta oxidation', 'https://en.wikipedia.org/w/index.php?title=Beta_oxidation&oldid=1343709246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Fatty acids are oxidized by most of the tissues in the body. However, some tissues such as the red blood cells of mammals (which do not contain mitochondria) and cells of the central nervous system do not use fatty acids for their energy requirements, but instead use carbohydrates (red blood cells and neurons) or ketone bodies (neurons only). Because many fatty acids are not fully saturated or do not have an even number of carbons, several different mechanisms have evolved, described below.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Beta oxidation: Even-numbered saturated fatty acids', 'Once inside the mitochondria, each cycle of β-oxidation, liberating a two carbon unit (acetyl-CoA), occurs in a sequence of four reactions: This process continues until the entire chain is cleaved into acetyl CoA units. The final cycle produces two separate acetyl CoAs, instead of one acyl CoA and one acetyl CoA. For every cycle, the Acyl CoA unit is shortened by two carbon atoms. Concomitantly, one molecule of FADH2, NADH and acetyl CoA are formed.', 'Wikipedia: Beta oxidation', 'https://en.wikipedia.org/w/index.php?title=Beta_oxidation&oldid=1343709246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Once inside the mitochondria, each cycle of β-oxidation, liberating a two carbon unit (acetyl-CoA), occurs in a sequence of four reactions: This process continues until the entire chain is cleaved into acetyl CoA units. The final cycle produces two separate acetyl CoAs, instead of one acyl CoA and one acetyl CoA. For every cycle, the Acyl CoA unit is shortened by two carbon atoms. Concomitantly, one molecule of FADH2, NADH and acetyl CoA are formed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Beta oxidation: Odd-numbered saturated fatty acids', 'Fatty acids with an odd number of carbons are found in the lipids of plants and some marine organisms. Many ruminant animals form a large amount of 3-carbon propionate during the fermentation of carbohydrates in the rumen. Long-chain fatty acids with an odd number of carbon atoms are found particularly in ruminant fat and milk. Chains with an odd-number of carbons are oxidized in the same manner as even-numbered chains, but the final products are propionyl-CoA and acetyl-CoA. Propionyl-CoA is first carboxylated using a bicarbonate ion into a D-stereoisomer of methylmalonyl-CoA. This reaction involves a biotin co-factor, ATP and the enzyme propionyl-CoA carboxylase. The bicarbonate ion''s carbon is added to the middle carbon of propionyl-CoA, forming a D-methylmalonyl-CoA. However, the D-conformation is enzymatically converted into the L-conformation by methylmalonyl-CoA epimerase. It then undergoes intramolecular rearrangement, which is catalyzed by methylmalonyl-CoA mutase (requiring B12 as a coenzyme) to form succinyl-CoA. The succinyl-CoA formed then enters the citric acid cycle.', 'Wikipedia: Beta oxidation', 'https://en.wikipedia.org/w/index.php?title=Beta_oxidation&oldid=1343709246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Fatty acids with an odd number of carbons are found in the lipids of plants and some marine organisms. Many ruminant animals form a large amount of 3-carbon propionate during the fermentation of carbohydrates in the rumen. Long-chain fatty acids with an odd number of carbon atoms are found particularly in ruminant fat and milk. Chains with an odd-number of carbons are oxidized in the same manner as even-numbered chains, but the final products are propionyl-CoA and acetyl-CoA. Propionyl-CoA is first carboxylated using a bicarbonate ion into a D-stereoisomer of methylmalonyl-CoA. This reaction involves a biotin co-factor, ATP and the enzyme propionyl-CoA carboxylase. The bicarbonate ion''s carbon is added to the middle carbon of propionyl-CoA, forming a D-methylmalonyl-CoA. However, the D-conformation is enzymatically converted into the L-conformation by methylmalonyl-CoA epimerase. It then undergoes intramolecular rearrangement, which is catalyzed by methylmalonyl-CoA mutase (requiring B12 as a coenzyme) to form succinyl-CoA. The succinyl-CoA formed then enters the citric acid cycle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Beta oxidation: Odd-numbered saturated fatty acids', 'However, whereas acetyl-CoA enters the citric acid cycle by condensing with an existing molecule of oxaloacetate, succinyl-CoA enters the cycle as a principal in its own right. Thus, the succinate just adds to the population of circulating molecules in the cycle and undergoes no net metabolization while in it. When this infusion of citric acid cycle intermediates exceeds cataplerotic demand (such as for aspartate or glutamate synthesis), some of them can be extracted to the gluconeogenesis pathway, in the liver and kidneys, through phosphoenolpyruvate carboxykinase, and converted to free glucose.', 'Wikipedia: Beta oxidation', 'https://en.wikipedia.org/w/index.php?title=Beta_oxidation&oldid=1343709246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'However, whereas acetyl-CoA enters the citric acid cycle by condensing with an existing molecule of oxaloacetate, succinyl-CoA enters the cycle as a principal in its own right. Thus, the succinate just adds to the population of circulating molecules in the cycle and undergoes no net metabolization while in it. When this infusion of citric acid cycle intermediates exceeds cataplerotic demand (such as for aspartate or glutamate synthesis), some of them can be extracted to the gluconeogenesis pathway, in the liver and kidneys, through phosphoenolpyruvate carboxykinase, and converted to free glucose.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Beta oxidation: Unsaturated fatty acids', 'β-Oxidation of unsaturated fatty acids poses a problem since the location of a cis-bond can prevent the formation of a trans-Δ2 bond which is essential for continuation of β-Oxidation as this conformation is ideal for enzyme catalysis. This is handled by additional two enzymes, Enoyl CoA isomerase and 2,4 Dienoyl CoA reductase. β-oxidation occurs normally until the acyl CoA (because of the presence of a double bond) is not an appropriate substrate for acyl CoA dehydrogenase, or enoyl CoA hydratase: If the acyl CoA contains a cis-Δ3 bond, then cis-Δ3-Enoyl CoA isomerase will convert the bond to a trans-Δ2 bond, which is a regular substrate. If the acyl CoA contains a cis-Δ4 double bond, then its dehydrogenation yields a 2,4-dienoyl intermediate, which is not a substrate for enoyl CoA hydratase. However, the enzyme 2,4 Dienoyl CoA reductase reduces the intermediate, using NADPH, into trans-Δ3-enoyl CoA. This compound is converted into a suitable intermediate by 3,2-Enoyl CoA isomerase and β-Oxidation continues.', 'Wikipedia: Beta oxidation', 'https://en.wikipedia.org/w/index.php?title=Beta_oxidation&oldid=1343709246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'β-Oxidation of unsaturated fatty acids poses a problem since the location of a cis-bond can prevent the formation of a trans-Δ2 bond which is essential for continuation of β-Oxidation as this conformation is ideal for enzyme catalysis. This is handled by additional two enzymes, Enoyl CoA isomerase and 2,4 Dienoyl CoA reductase. β-oxidation occurs normally until the acyl CoA (because of the presence of a double bond) is not an appropriate substrate for acyl CoA dehydrogenase, or enoyl CoA hydratase: If the acyl CoA contains a cis-Δ3 bond, then cis-Δ3-Enoyl CoA isomerase will convert the bond to a trans-Δ2 bond, which is a regular substrate. If the acyl CoA contains a cis-Δ4 double bond, then its dehydrogenation yields a 2,4-dienoyl intermediate, which is not a substrate for enoyl CoA hydratase. However, the enzyme 2,4 Dienoyl CoA reductase reduces the intermediate, using NADPH, into trans-Δ3-enoyl CoA. This compound is converted into a suitable intermediate by 3,2-Enoyl CoA isomerase and β-Oxidation continues.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycogen', 'Glycogen is a multibranched polysaccharide of glucose that serves as a form of energy storage in animals, fungi, and bacteria. It is the main storage form of glucose in the human body. Glycogen functions as one of three regularly used forms of energy reserves, creatine phosphate being for very short-term, glycogen being for short-term and the triglyceride stores in adipose tissue (i.e., body fat) being for long-term storage. Protein, broken down into amino acids, is seldom used as a main energy source except during starvation and glycolytic crisis (see bioenergetic systems). In humans, glycogen is made and stored primarily in the cells of the liver and skeletal muscle. In the liver, glycogen can make up 5–6% of the organ''s fresh weight: the liver of an adult, weighing 1.5 kg, can store roughly 100–120 grams of glycogen. In skeletal muscle, glycogen is found in a low concentration (1–2% of the muscle mass): the skeletal muscle of an adult weighing 70 kg stores roughly 400 grams of glycogen. Small amounts of glycogen are also found in other tissues and cells, including the kidneys, red blood cells, white blood cells, and glial cells in the brain. The uterus also stores glycogen during pregnancy to nourish the embryo.', 'Wikipedia: Glycogen', 'https://en.wikipedia.org/w/index.php?title=Glycogen&oldid=1357487126', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Glycogen is a multibranched polysaccharide of glucose that serves as a form of energy storage in animals, fungi, and bacteria. It is the main storage form of glucose in the human body. Glycogen functions as one of three regularly used forms of energy reserves, creatine phosphate being for very short-term, glycogen being for short-term and the triglyceride stores in adipose tissue (i.e., body fat) being for long-term storage. Protein, broken down into amino acids, is seldom used as a main energy source except during starvation and glycolytic crisis (see bioenergetic systems). In humans, glycogen is made and stored primarily in the cells of the liver and skeletal muscle. In the liver, glycogen can make up 5–6% of the organ''s fresh weight: the liver of an adult, weighing 1.5 kg, can store roughly 100–120 grams of glycogen. In skeletal muscle, glycogen is found in a low concentration (1–2% of the muscle mass): the skeletal muscle of an adult weighing 70 kg stores roughly 400 grams of glycogen. Small amounts of glycogen are also found in other tissues and cells, including the kidneys, red blood cells, white blood cells, and glial cells in the brain. The uterus also stores glycogen during pregnancy to nourish the embryo.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycogen', 'The amount of glycogen stored in the body mostly depends on oxidative type 1 fibres, physical training, basal metabolic rate, and eating habits. Different levels of resting muscle glycogen are reached by changing the number of glycogen particles, rather than increasing the size of existing particles though most glycogen particles at rest are smaller than their theoretical maximum. Approximately 4 grams of glucose are present in the blood of humans at all times; in fasting individuals, blood glucose is maintained constant at this level at the expense of glycogen stores, primarily from the liver (glycogen in skeletal muscle is mainly used as an immediate source of energy for that muscle rather than being used to maintain physiological blood glucose levels). Glycogen stores in skeletal muscle serve as a form of energy storage for the muscle itself; however, the breakdown of muscle glycogen impedes muscle glucose uptake from the blood, thereby increasing the amount of blood glucose available for use in other tissues. Liver glycogen stores serve as a store of glucose for use throughout the body, particularly the central nervous system. The human brain consumes approximately 60% of blood glucose in fasted, sedentary individuals.', 'Wikipedia: Glycogen', 'https://en.wikipedia.org/w/index.php?title=Glycogen&oldid=1357487126', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'The amount of glycogen stored in the body mostly depends on oxidative type 1 fibres, physical training, basal metabolic rate, and eating habits. Different levels of resting muscle glycogen are reached by changing the number of glycogen particles, rather than increasing the size of existing particles though most glycogen particles at rest are smaller than their theoretical maximum. Approximately 4 grams of glucose are present in the blood of humans at all times; in fasting individuals, blood glucose is maintained constant at this level at the expense of glycogen stores, primarily from the liver (glycogen in skeletal muscle is mainly used as an immediate source of energy for that muscle rather than being used to maintain physiological blood glucose levels). Glycogen stores in skeletal muscle serve as a form of energy storage for the muscle itself; however, the breakdown of muscle glycogen impedes muscle glucose uptake from the blood, thereby increasing the amount of blood glucose available for use in other tissues. Liver glycogen stores serve as a store of glucose for use throughout the body, particularly the central nervous system. The human brain consumes approximately 60% of blood glucose in fasted, sedentary individuals.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycogen', 'Glycogen is an analogue of starch, a glucose polymer that functions as energy storage in plants. It has a structure similar to amylopectin (a component of starch), but is more extensively branched and compact than starch. Both are white powders in their dry state. Glycogen is found in the form of granules in the cytosol/cytoplasm in many cell types, and plays an important role in the glucose cycle. Glycogen forms an energy reserve that can be quickly mobilized to meet a sudden need for glucose, but one that is less compact than the energy reserves of triglycerides (lipids). As such it is also found as storage reserve in many parasitic protozoa.', 'Wikipedia: Glycogen', 'https://en.wikipedia.org/w/index.php?title=Glycogen&oldid=1357487126', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Glycogen is an analogue of starch, a glucose polymer that functions as energy storage in plants. It has a structure similar to amylopectin (a component of starch), but is more extensively branched and compact than starch. Both are white powders in their dry state. Glycogen is found in the form of granules in the cytosol/cytoplasm in many cell types, and plays an important role in the glucose cycle. Glycogen forms an energy reserve that can be quickly mobilized to meet a sudden need for glucose, but one that is less compact than the energy reserves of triglycerides (lipids). As such it is also found as storage reserve in many parasitic protozoa.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycogen: Structure', 'Glycogen is a branched biopolymer consisting of linear chains of glucose residues with an average chain length of approximately 8–12 glucose units and 2,000-60,000 residues per one molecule of glycogen. Being a branched chain without any loops, the empirical formula is C6nH10n+2O5n+1, equivalent to (C6H10O5)n plus H2O. Like amylopectin, glucose units are linked together linearly by α(1→4) glycosidic bonds from one glucose to the next. Branches are linked to the chains from which they are branching off by α(1→6) glycosidic bonds between the first glucose of the new branch and a glucose on the stem chain. Each glycogen is essentially a ball of glucose trees, with around 12 layers, centered on a glycogenin protein, with three kinds of glucose chains: A, B, and C. There is only one C-chain, attached to the glycogenin. This C-chain is formed by the self-glucosylation of the glycogenin, forming a short primer chain. From the C-chain grows out B-chains, and from B-chains branch out B- and A-chains. The B-chains have on average 2 branch points, while the A-chains are terminal, thus unbranched. On average, each chain has length 12, tightly constrained to be between 11 and 15. All A-chains reach the spherical surface of the glycogen.', 'Wikipedia: Glycogen', 'https://en.wikipedia.org/w/index.php?title=Glycogen&oldid=1357487126', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Glycogen is a branched biopolymer consisting of linear chains of glucose residues with an average chain length of approximately 8–12 glucose units and 2,000-60,000 residues per one molecule of glycogen. Being a branched chain without any loops, the empirical formula is C6nH10n+2O5n+1, equivalent to (C6H10O5)n plus H2O. Like amylopectin, glucose units are linked together linearly by α(1→4) glycosidic bonds from one glucose to the next. Branches are linked to the chains from which they are branching off by α(1→6) glycosidic bonds between the first glucose of the new branch and a glucose on the stem chain. Each glycogen is essentially a ball of glucose trees, with around 12 layers, centered on a glycogenin protein, with three kinds of glucose chains: A, B, and C. There is only one C-chain, attached to the glycogenin. This C-chain is formed by the self-glucosylation of the glycogenin, forming a short primer chain. From the C-chain grows out B-chains, and from B-chains branch out B- and A-chains. The B-chains have on average 2 branch points, while the A-chains are terminal, thus unbranched. On average, each chain has length 12, tightly constrained to be between 11 and 15. All A-chains reach the spherical surface of the glycogen.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycogen: Structure', 'Glycogen in muscle, liver, and fat cells is stored in a hydrated form, composed of three or four parts of water per part of glycogen associated with 0.45 millimoles (18 mg) of potassium per gram of glycogen. Glucose is an osmotic molecule, and can have profound effects on osmotic pressure in high concentrations possibly leading to cell damage or death if stored in the cell without being modified. Glycogen is a non-osmotic molecule, so it can be used as a solution to storing glucose in the cell without disrupting osmotic pressure.', 'Wikipedia: Glycogen', 'https://en.wikipedia.org/w/index.php?title=Glycogen&oldid=1357487126', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Glycogen in muscle, liver, and fat cells is stored in a hydrated form, composed of three or four parts of water per part of glycogen associated with 0.45 millimoles (18 mg) of potassium per gram of glycogen. Glucose is an osmotic molecule, and can have profound effects on osmotic pressure in high concentrations possibly leading to cell damage or death if stored in the cell without being modified. Glycogen is a non-osmotic molecule, so it can be used as a solution to storing glucose in the cell without disrupting osmotic pressure.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycogen: Liver', 'As a meal containing carbohydrates or protein is eaten and digested, blood glucose levels rise, and the pancreas secretes insulin. Blood glucose from the portal vein enters liver cells (hepatocytes). Insulin acts on the hepatocytes to stimulate the action of several enzymes, including glycogen synthase. Glucose molecules are added to the chains of glycogen as long as both insulin and glucose remain plentiful. In this postprandial or "fed" state, the liver takes in more glucose from the blood than it releases. After a meal has been digested and glucose levels begin to fall, insulin secretion is reduced, and glycogen synthesis stops. When it is needed for energy, glycogen is broken down and converted again to glucose. Glycogen phosphorylase is the primary enzyme of glycogen breakdown. For the next 8–12 hours, glucose derived from liver glycogen is the primary source of blood glucose used by the rest of the body for fuel. Glucagon, another hormone produced by the pancreas, in many respects serves as a countersignal to insulin. In response to insulin levels being below normal (when blood levels of glucose begin to fall below the normal range), glucagon is secreted in increasing amounts and stimulates both glycogenolysis (the breakdown of glycogen) and gluconeogenesis (the production of glucose from other sources).', 'Wikipedia: Glycogen', 'https://en.wikipedia.org/w/index.php?title=Glycogen&oldid=1357487126', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'As a meal containing carbohydrates or protein is eaten and digested, blood glucose levels rise, and the pancreas secretes insulin. Blood glucose from the portal vein enters liver cells (hepatocytes). Insulin acts on the hepatocytes to stimulate the action of several enzymes, including glycogen synthase. Glucose molecules are added to the chains of glycogen as long as both insulin and glucose remain plentiful. In this postprandial or "fed" state, the liver takes in more glucose from the blood than it releases. After a meal has been digested and glucose levels begin to fall, insulin secretion is reduced, and glycogen synthesis stops. When it is needed for energy, glycogen is broken down and converted again to glucose. Glycogen phosphorylase is the primary enzyme of glycogen breakdown. For the next 8–12 hours, glucose derived from liver glycogen is the primary source of blood glucose used by the rest of the body for fuel. Glucagon, another hormone produced by the pancreas, in many respects serves as a countersignal to insulin. In response to insulin levels being below normal (when blood levels of glucose begin to fall below the normal range), glucagon is secreted in increasing amounts and stimulates both glycogenolysis (the breakdown of glycogen) and gluconeogenesis (the production of glucose from other sources).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycogen: Muscle', 'Muscle glycogen appears to function as a reserve of quickly available phosphorylated glucose, in the form of glucose-1-phosphate, for muscle cells. Glycogen contained within skeletal muscle cells are primarily in the form of β particles. Other cells that contain small amounts use it locally as well. As muscle cells lack glucose-6-phosphatase, which is required to pass glucose into the blood, the glycogen they store is available solely for internal use and is not shared with other cells. This is in contrast to liver cells, which, on demand, readily do break down their stored glycogen into glucose and send it through the blood stream as fuel for other organs. Skeletal muscle needs ATP (provides energy) for muscle contraction and relaxation. Skeletal muscle relies predominantly on glycogenolysis for the first few minutes as it transitions from rest to activity, as well as throughout high-intensity aerobic activity and all anaerobic activity. During anaerobic activity, such as weightlifting and isometric exercise, the phosphagen system (ATP-PCr) and muscle glycogen are the only substrates used as they do not require oxygen nor blood flow.', 'Wikipedia: Glycogen', 'https://en.wikipedia.org/w/index.php?title=Glycogen&oldid=1357487126', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Muscle glycogen appears to function as a reserve of quickly available phosphorylated glucose, in the form of glucose-1-phosphate, for muscle cells. Glycogen contained within skeletal muscle cells are primarily in the form of β particles. Other cells that contain small amounts use it locally as well. As muscle cells lack glucose-6-phosphatase, which is required to pass glucose into the blood, the glycogen they store is available solely for internal use and is not shared with other cells. This is in contrast to liver cells, which, on demand, readily do break down their stored glycogen into glucose and send it through the blood stream as fuel for other organs. Skeletal muscle needs ATP (provides energy) for muscle contraction and relaxation. Skeletal muscle relies predominantly on glycogenolysis for the first few minutes as it transitions from rest to activity, as well as throughout high-intensity aerobic activity and all anaerobic activity. During anaerobic activity, such as weightlifting and isometric exercise, the phosphagen system (ATP-PCr) and muscle glycogen are the only substrates used as they do not require oxygen nor blood flow.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'metabolism', 'Glycogen: Muscle', 'Different bioenergetic systems produce ATP at different speeds, with ATP produced from muscle glycogen being much faster than fatty acid oxidation. The level of exercise intensity determines how much of which substrate (fuel) is used for ATP synthesis also. Muscle glycogen can supply a much higher rate of substrate for ATP synthesis than blood glucose. During maximum intensity exercise, muscle glycogen can supply 40 mmol glucose/kg wet weight/minute, whereas blood glucose can supply 4 – 5 mmol. Due to its high supply rate and quick ATP synthesis, during high-intensity aerobic activity (such as brisk walking, jogging, or running), the higher the exercise intensity, the more the muscle cell produces ATP from muscle glycogen. This reliance on muscle glycogen is not only to provide the muscle with enough ATP during high-intensity exercise, but also to maintain blood glucose homeostasis (that is, to not become hypoglycaemic by the muscles needing to extract far more glucose from the blood than the liver can provide). A deficit of muscle glycogen leads to muscle fatigue known as "hitting the wall" or "the bonk" (see below under glycogen depletion).', 'Wikipedia: Glycogen', 'https://en.wikipedia.org/w/index.php?title=Glycogen&oldid=1357487126', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'metabolism' and body = 'Different bioenergetic systems produce ATP at different speeds, with ATP produced from muscle glycogen being much faster than fatty acid oxidation. The level of exercise intensity determines how much of which substrate (fuel) is used for ATP synthesis also. Muscle glycogen can supply a much higher rate of substrate for ATP synthesis than blood glucose. During maximum intensity exercise, muscle glycogen can supply 40 mmol glucose/kg wet weight/minute, whereas blood glucose can supply 4 – 5 mmol. Due to its high supply rate and quick ATP synthesis, during high-intensity aerobic activity (such as brisk walking, jogging, or running), the higher the exercise intensity, the more the muscle cell produces ATP from muscle glycogen. This reliance on muscle glycogen is not only to provide the muscle with enough ATP during high-intensity exercise, but also to maintain blood glucose homeostasis (that is, to not become hypoglycaemic by the muscles needing to extract far more glucose from the blood than the liver can provide). A deficit of muscle glycogen leads to muscle fatigue known as "hitting the wall" or "the bonk" (see below under glycogen depletion).');
commit;
